<script>
  const months = ["January","February","March","April","May","June","July"];
  let values = [[65,8,90,81,56,55,40],[21,48,40,19,96,27,99]];
  const svg = document.getElementById("chartSvg");
  let dotsEnabled = false;

  function smoothPath(points) {
    if (!points.length) return "";
    let d = `M ${points[0].x} ${points[0].y}`;
    for (let i = 0; i < points.length - 1; i++) {
      const p0 = points[Math.max(0, i - 1)], p1 = points[i];
      const p2 = points[i + 1], p3 = points[Math.min(points.length - 1, i + 2)];
      const c1x = p1.x + (p2.x - p0.x) / 6, c1y = p1.y + (p2.y - p0.y) / 6;
      const c2x = p2.x - (p3.x - p1.x) / 6, c2y = p2.y - (p3.y - p1.y) / 6;
      d += ` C ${c1x} ${c1y}, ${c2x} ${c2y}, ${p2.x} ${p2.y}`;
    }
    return d;
  }
  function drawChart() {
    const left = 40, right = 637, top = 13, bottom = 203;
    const xStep = (right-left)/6;
    const y = n => bottom - (Number(n || 0) / 100) * (bottom-top);
    let out = "";
    for (let n=0; n<=100; n+=10) {
      const yy = y(n);
      out += `<line x1="${left}" y1="${yy}" x2="${right}" y2="${yy}" stroke="#dedede" stroke-width="1"/>`;
      out += `<text x="27" y="${yy+4}" text-anchor="end" font-size="12" fill="#333">${n}</text>`;
    }
    months.forEach((m,i) => {
      const xx = left + i*xStep;
      out += `<line x1="${xx}" y1="${top}" x2="${xx}" y2="${bottom}" stroke="#e5e5e5" stroke-width="1"/>`;
      out += `<text x="${xx}" y="223" text-anchor="middle" font-size="13" fill="#333">${m}</text>`;
    });
    out += `<line x1="${left}" y1="${bottom}" x2="${right}" y2="${bottom}" stroke="#333" stroke-width="1"/>`;
    out += `<line x1="${left}" y1="${top}" x2="${left}" y2="${bottom}" stroke="#333" stroke-width="1"/>`;
    const series = values.map(arr => arr.map((v,i)=>({x:left+i*xStep,y:y(v)})));
    const blueLine = smoothPath(series[0]), greenLine = smoothPath(series[1]);
    out += `<path d="${blueLine} L ${right} ${bottom} L ${left} ${bottom} Z" fill="rgba(65,164,215,.42)" stroke="#3498d0" stroke-width="2"/>`;
    out += `<path d="${greenLine} L ${right} ${bottom} L ${left} ${bottom} Z" fill="rgba(43,215,129,.55)" stroke="#26d96f" stroke-width="2"/>`;
    series.forEach((pts,s) => pts.forEach((p,i) => {
      const val = values[s][i];
      out += `<text x="${p.x}" y="${Math.max(10,p.y-8)}" text-anchor="middle" font-size="12" font-style="italic" fill="#333">${val}</text>`;
      if (dotsEnabled) out += `<circle cx="${p.x}" cy="${p.y}" r="5" fill="${s ? '#24d46a' : '#329bd3'}" stroke="#fff" stroke-width="1"/>`;
    }));
    svg.innerHTML = out;
  }
  drawChart();

  const cells = [...document.querySelectorAll('td[data-series]')];
  let selected = null;
  function commitCell(cell) {
    if (!cell) return;
    const s = Number(cell.dataset.series), i = Number(cell.dataset.index);
    const text = cell.textContent.trim();
    values[s][i] = text === "" ? 0 : (Number(text) || 0);
    cell.contentEditable = "false";
    cell.classList.remove("editing");
    drawChart();
  }
  function beginEdit(cell, replace) {
    if (selected && selected !== cell && selected.isContentEditable) commitCell(selected);
    selected = cell;
    cells.forEach(c => c.classList.toggle("selected", c === cell));
    cell.contentEditable = "true";
    cell.classList.add("editing");
    if (replace) cell.textContent = "";
    cell.focus();
    const range = document.createRange();
    range.selectNodeContents(cell);
    range.collapse(false);
    const sel = window.getSelection();
    sel.removeAllRanges(); sel.addRange(range);
  }
  cells.forEach(cell => {
    cell.addEventListener("click", () => {
      if (selected && selected !== cell && selected.isContentEditable) commitCell(selected);
      selected = cell;
      cells.forEach(c => c.classList.toggle("selected", c === cell));
    });
    cell.addEventListener("dblclick", () => beginEdit(cell, false));
    cell.addEventListener("keydown", e => {
      if (e.key === "Enter") { e.preventDefault(); commitCell(cell); cell.blur(); }
      else if (e.key === "Escape") { cell.textContent = values[cell.dataset.series][cell.dataset.index]; commitCell(cell); }
    });
    cell.addEventListener("input", () => {
      const s = Number(cell.dataset.series), i = Number(cell.dataset.index);
      values[s][i] = Number(cell.textContent.trim()) || 0;
      drawChart();
    });
    cell.addEventListener("blur", () => { if (cell.isContentEditable) commitCell(cell); });
  });
  document.addEventListener("keydown", e => {
    if (!selected || selected.isContentEditable || e.ctrlKey || e.metaKey || e.altKey) return;
    if (/^[0-9.-]$/.test(e.key)) { e.preventDefault(); beginEdit(selected, true); document.execCommand("insertText", false, e.key); }
    else if (e.key === "Backspace" || e.key === "Delete") { e.preventDefault(); beginEdit(selected, true); }
  });

  const rows = [...document.querySelectorAll(".acc-row")];
  rows.forEach(row => row.addEventListener("click", () => {
    const content = row.nextElementSibling;
    const wasOpen = content.classList.contains("open");
    document.querySelectorAll(".acc-content").forEach(c => c.classList.remove("open"));
    if (!wasOpen) {
      content.classList.add("open");
      if (row.textContent.trim().startsWith("Point Dot")) {
        setTimeout(() => row.scrollIntoView({block:"center", behavior:"smooth"}), 10);
      }
    }
  }));
  document.querySelector(".switch").addEventListener("change", e => {
    dotsEnabled = e.target.checked;
    drawChart();
  });
</script>
